mapper.select:
select throttle_id, throttle_key, channel, target_ref, last_touch_time, touch_count_24h, create_time, update_time
from sys_action_center_touch_throttle
where throttle_key = #{throttleKey}

mapper.insert:
insert into sys_action_center_touch_throttle (
	throttle_key, channel, target_ref, last_touch_time, touch_count_24h, create_time, update_time
) values (
	#{throttleKey}, #{channel}, #{targetRef}, #{lastTouchTime}, #{touchCount24h}, sysdate(), sysdate()
)
